def solve_sequence():
    a = {1: 1, 2: 1}
    N = 30
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        try:
            val1 = a[a[n-1]]
            val2 = a[n - a[n-1]]
            a[n] = val1 + val2
        except KeyError:
            # This should not happen if we calculate iteratively, 
            # as both arguments a_{n-1} and n - a_{n-1} must be less than n.
            # Check: a_{n-1} < n-1 if n >= 3, so a_{n-1} < n.
            # Check: n - a_{n-1}. Since a_{n-1} >= 1, n - a_{n-1} <= n-1.
            print(f"Error: Missing entry for n={n}")
            return None

    return a

sequence_values = solve_sequence()

if sequence_values:
    print("n | a_n")
    for n in range(1, 31):
        print(f"{n:2} | {sequence_values[n]}")
